window.products.push({"id":286572,"name":"6Pcs Regular Mouth Mushroom Liquid Culture Lid Grain Spawn Cultivation Mason Jar Lid with 0.2 Micron PTFE Syringe Filter & 20mm Self Healing Injection","category":"homeandappliances","retail price":21.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/81sABHPAWWL._AC_SL1500_.jpg","description":"Quantity:6pcs Colour:gold Lid Material: Tinplate Lid diameter:70mm Fit for all Regular Mouth jars The Lid comes with a self healing injection for injecting culture and a PTFE syringe filter for avoid contamination . These lids can be used in a microwave, autoclave or pressure cooker. Our professional grade autoclavable regular mouth jar lids are built to be lab-quality, and made specifically for liquid culturing . Leave the lids a quarter turn loose while in the pressure cooker so air can escape, otherwise the injection ports will pop out.","images":["https://m.media-amazon.com/images/I/81sABHPAWWL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Biomed Solutions","source_asin":"B091MFLJS9","category_path":"Home & Kitchen"},"sku":"BM-286572","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B091MFLJS9","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B091MFLJS9","price_pending":true,"merchant_ready":false});
